=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to decide which type of deactivation shall be triggered */

// Init
HoldDeactRampPlain = 0;	
HoldDeactRampTime = 0;
HoldDeactRampj = 0;
HoldDeactRampTime2Move = 0;
HoldDeactRampHyperbel = 0;
HoldDeactRampjCus = 0;
HoldDeactRampTCus = 0;
HoldDeactRampReserved1 = 0;
HoldDeactRampReserved2 = 0;

// Define standard deactivation
if(CsmHoldDeactReqActive > 0)
{
	CsmHoldDeactActive = true;
	
	// in case default ramp is triggered CSM decide based on vehicle conditions
	// which ramp shall be used
	if(CsmHoldDeactRampDefault >= 1)
	{
		if(CsmParkBrakeApplied == true)
		{
			HoldDeactRampTime2Move = CsmHoldDeactRampDefault;
		}		else if(SkidYawRate == true)
		{
			HoldDeactRampPlain = CsmHoldDeactRampDefault;
		}		else
		{
			HoldDeactRampTime = CsmHoldDeactRampDefault;
		}
	}
	HoldDeactRampPlain = HoldDeactRampPlain.max(CsmHoldDeactRampPlain);
	HoldDeactRampTime = HoldDeactRampTime.max(CsmHoldDeactRampTime);
	HoldDeactRampj = HoldDeactRampj.max(CsmHoldDeactRampj);
	HoldDeactRampTime2Move = HoldDeactRampTime2Move.max(CsmHoldDeactRampTime2Move);
	HoldDeactRampHyperbel = HoldDeactRampHyperbel.max(CsmHoldDeactRampHyperbel);
	HoldDeactRampjCus = HoldDeactRampjCus.max(CsmHoldDeactRampjCus);
	HoldDeactRampTCus = HoldDeactRampTCus.max(CsmHoldDeactRampTCus);
	HoldDeactRampReserved1 = HoldDeactRampReserved1.max(CsmHoldDeactRampReserved1);
	HoldDeactRampReserved2 = HoldDeactRampReserved2.max(CsmHoldDeactRampReserved2);
}
else
{
	CsmHoldDeactActive = false;
	
	HoldDeactRampPlain = 0;
	HoldDeactRampTime = 0;
	HoldDeactRampj = 0;
	HoldDeactRampTime2Move = 0;
	HoldDeactRampHyperbel = 0;
	HoldDeactRampjCus = 0;
	HoldDeactRampTCus = 0;
	HoldDeactRampReserved1 = 0;
	HoldDeactRampReserved2 = 0;
}


